#!/usr/bin/env node
/**
 * tred-schemas-de-prof.mjs
 *
 * Les schemas electriques composes par CircuiTikz — l'outil dont se servent
 * les professeurs d'ingenierie allemands — au lieu de SVG dessine a la main
 * par le modele, coordonnee par coordonnee.
 *
 *   Dockerfile        TeX Live minimal + circuitikz + dvisvgm + mutool
 *   railway.json      bascule sur le Dockerfile
 *   lib/tikz.ts       circuitikz dans le preambule, repli si absent
 *   diagram-blocks    le client compile a nouveau (serveur, pas navigateur)
 *   prompt NIVEAU 9c  le plafond des 8 dessins figes est leve
 *   /api/agent/exercise  vrai niveau de Klausur, temps, bareme, circuits
 *
 * ATTENTION — ceci change ta construction Railway. Pour revenir en arriere :
 * remettre dans railway.json
 *     "build": { "buildCommand": "bun install && bun run build:web" }
 * L'application fonctionne sans LaTeX ; elle perd seulement les schemas.
 *
 * Verifie ici : pdflatex + dvisvgm + mutool installes pour de vrai, un
 * diviseur de tension et un amplificateur operationnel compiles par la
 * fonction du serveur, bun install --frozen-lockfile 0, build:web 0,
 * tsc 0, bun test 146/146, vite build.
 *
 * NON verifie : la construction de l'image elle-meme (pas de demon Docker
 * ici). C'est le seul risque de cette livraison.
 *
 *   node tred-schemas-de-prof.mjs
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Depot introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Depot :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
let n = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  n++;
}
for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) rmSync(cible);
}

console.log(`${n} fichiers poses.\n`);
console.log("1) La base, si ce n'est pas deja fait :");
console.log("     node migre-cours.mjs");
console.log("\n2) L'envoi. La premiere construction prendra 4 a 6 minutes");
console.log("   de plus : Railway installe TeX Live.");
console.log("     git add -A");
console.log("     git commit -m \"schemas circuitikz, exercices au niveau Klausur\"");
console.log("     git push");
console.log("\n3) Regarde le journal Railway. La ligne a attendre est :");
console.log("     chaine LaTeX complete");
console.log("   Si elle manque, l'image n'a pas circuitikz et il faut le dire.");
